import java.util.Scanner;

public class Main {
    static int mod;
    static int maxN = 100000;
    static int[] factorials = new int[maxN + 1];
    static int[] inv_factorials = new int[maxN + 1];
    static int[] inv_numbers = new int[maxN + 1];
    static PairStruct[] dp_array = new PairStruct[maxN + 1];
    static PairStruct[][] prefix_table = new PairStruct[maxN + 1][maxN + 1];

    static class PairStruct {
        int first, second;

        PairStruct(int f, int s) {
            this.first = f;
            this.second = s;
        }

        PairStruct add(PairStruct other) {
            return new PairStruct(add_modulo(this.first + other.first), add_modulo(this.second + other.second));
        }

        PairStruct multiply(PairStruct other) {
            long newFirst = ((long) this.first * other.first) % mod;
            long newSecond = ((long) this.first * other.second + (long) this.second * other.first) % mod;
            return new PairStruct((int) newFirst, (int) newSecond);
        }
    }

    static int add_modulo(int x) {
        return x >= mod ? x - mod : x;
    }

    static int subtract_modulo(int x) {
        return x < 0 ? x + mod : x;
    }

    static int fast_power(int base, int exponent) {
        long result = 1;
        long b = base;
        int e = exponent;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return (int) result;
    }

    static int sum_series_final(int x) {
        long val = (long) x * (x + 1) / 2 % mod;
        return (int) val;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        mod = sc.nextInt();

        factorials[0] = 1;
        inv_factorials[0] = 1;
        for (int i = 1; i <= maxN; i++) {
            factorials[i] = (int) (((long) i * factorials[i - 1]) % mod);
            inv_factorials[i] = fast_power(factorials[i], mod - 2);
            inv_numbers[i] = fast_power(i, mod - 2);
        }

        for (int i = 0; i <= n; i++) {
            dp_array[i] = new PairStruct(0, 0);
        }
        dp_array[0] = new PairStruct(1, 0);

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                PairStruct temp = dp_array[j - 1].multiply(dp_array[i - j]);
                long tempSecond = ((long) temp.second * (i + 1) % mod + (long) temp.first * (add_modulo(sum_series_final(j - 1) + sum_series_final(i - j))) % mod) % mod;
                temp.second = (int) tempSecond;
                long tempSecondAdjusted = (tempSecond * inv_numbers[i]) % mod;
                temp.second = (int) tempSecondAdjusted;
                long tempFirst = ((long) temp.first * (i + 1) % mod) * inv_numbers[i] % mod;
                temp.first = (int) tempFirst;
                dp_array[i] = dp_array[i].add(temp);
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                prefix_table[i][j] = new PairStruct(0, 0);
            }
        }

        prefix_table[0][0] = new PairStruct(1, 0);
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= Math.min(i, m); j++) {
                if (i == j) {
                    prefix_table[i][j] = dp_array[i];
                }
                for (int k = 0; k < j && k < i; k++) {
                    prefix_table[i][j] = prefix_table[i][j].add(dp_array[k].multiply(prefix_table[i - k - 1][j - k]));
                }
            }
        }

        long answer_final = ((long) prefix_table[n][m].second * factorials[m]) % mod;
        System.out.println((int) answer_final);
        sc.close();
    }
}
